/**
 * Clean Markdown for the files generated by vitepress-plugin-llmstxt.
 *
 * The plugin copies each page's Markdown source into `<page>.md` and `llms-full.txt`.
 * That source is written for VitePress, not for a reader:
 *
 * - dynamic routes (registry tools, standards, generated categories) are Vue templates
 *   (`{{ $params.details.purpose }}`, `v-if`, `<ToolPubliccodeView />`) with no content
 * - hand-crafted pages use Vue components (`<ToolsFilter />`, `<RelatedCategories />`, `<RelatedStandards />`)
 *   that render nothing as text, and tool pages rely on the Quick Info block that
 *   napCoreMarkdownPlugin injects at render time
 *
 * This module rebuilds dynamic pages from the same data the site renders, and replaces
 * components on hand-crafted pages with the lists they would show.
 */

import fs from 'fs';
import path from 'path';
import { parse as parseYaml } from 'yaml';
import { withBasePath } from '../config/site';
import categoriesDataLoader, { type CategoryData } from '../data-loaders/categories.data';
import standardsDataLoader, { type Standard } from '../data-loaders/standards.data';
import toolsDataLoader, { type Tool } from '../data-loaders/tools.data';
import { type PostVisibility, isPostVisible } from '../utils/postVisibility';

/** The page shape the plugin passes to its `transform` hook. */
export interface LlmsPage {
  path: string;
  url: string;
  title: string;
  llmUrl: string;
  frontmatter: Record<string, unknown>;
  content: string;
}

/** Site data needed to write the pages. Loaded once per build. */
export interface LlmsContext {
  tools: Tool[];
  standards: Record<string, Standard>;
  categories: Record<string, CategoryData>;
  /** True when the page has a Markdown file on disk (false for dynamic routes). */
  hasSourceFile: (pagePath: string) => boolean;
  /** Site base path ("/" or "/sub/"); the plugin writes links without it. */
  base: string;
}

export function loadLlmsContext(srcDir: string, base: string): LlmsContext {
  return {
    tools: toolsDataLoader.load(),
    standards: standardsDataLoader.load(),
    categories: categoriesDataLoader.load(),
    hasSourceFile: (pagePath) => fs.existsSync(path.join(srcDir, pagePath)),
    base,
  };
}

/** Converts Windows separators from the plugin's path.join to URL slashes. */
export function toUrlPath(s: string): string {
  return s.replace(/\\+/g, '/').replace(/\/{2,}/g, '/');
}

const FRONTMATTER = /^---\n[\s\S]*?\n---\n*/;
const FRONTMATTER_YAML = /^---\n([\s\S]*?)\n---/;

/**
 * Blog posts the blog does not show (drafts, and scheduled posts outside preview mode),
 * as `ignore` globs for the plugin, so they stay out of llms.txt and llms-full.txt.
 * The `**` prefix is needed because the globs are matched against absolute paths.
 */
export function hiddenBlogPosts(srcDir: string): string[] {
  const dir = path.join(srcDir, 'blog', 'posts');
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir)
    .filter((file) => file.endsWith('.md'))
    .filter((file) => {
      const source = fs.readFileSync(path.join(dir, file), 'utf-8').replace(/\r\n/g, '\n');
      const yaml = FRONTMATTER_YAML.exec(source)?.[1];
      const frontmatter = ((yaml && parseYaml(yaml)) ?? {}) as PostVisibility;
      return !isPostVisible(frontmatter);
    })
    .map((file) => `**/blog/posts/${file}`);
}

/** Fixes the link targets in llms.txt: URL slashes and the site base. */
export function fixIndexLinks(content: string, base: string): string {
  return content.replace(/\]\(([^)]*)\)/g, (_m, url: string) => `](${withBasePath(toUrlPath(url), base)})`);
}

function llmsLink(section: string, slug: string): string {
  return `/${section}/${slug}.md`;
}

function toolList(tools: Tool[]): string {
  if (tools.length === 0) return '_No tools listed yet._';
  return [...tools]
    .sort((a, b) => a.title.localeCompare(b.title))
    .map((t) => `- [${t.title}](${llmsLink('tools', t.slug)})${t.description ? `: ${t.description}` : ''}`)
    .join('\n');
}

function categoryList(slugs: string[], ctx: LlmsContext): string {
  return slugs
    .filter((s) => ctx.categories[s])
    .map((s) => `- [${ctx.categories[s].title}](${llmsLink('categories', s)}): ${ctx.categories[s].description}`)
    .join('\n');
}

function standardList(slugs: string[], ctx: LlmsContext): string {
  return slugs
    .filter((s) => ctx.standards[s])
    .map((s) => `- [${ctx.standards[s].title}](${llmsLink('standards', s)})`)
    .join('\n');
}

function titles(slugs: string[] | undefined, lookup: Record<string, { title: string }>): string {
  return (slugs ?? []).map((s) => lookup[s]?.title ?? s).join(', ');
}

/** The Quick Info facts shown at the top of a tool page, as a Markdown list. */
export function toolQuickInfo(tool: Tool, ctx: LlmsContext): string {
  const rows: [string, string | undefined][] = [
    ['Repository', tool.repository],
    ['Website', tool.website],
    ['Documentation', tool.documentation],
    ['Demo', tool.demo],
    ['Status', tool.status],
    ['Licence', tool.license],
    ['Developer', tool.developer],
    ['Maintained by', tool.maintainedBy],
    ['Main contributor', tool.mainContributor],
    ['Type', Array.isArray(tool.type) ? tool.type.join(', ') : tool.type],
    ['Technology', tool.technology],
    ['Language', tool.language],
    ['Version', tool.softwareVersion],
    ['First release', tool.firstRelease],
    ['Last updated', tool.lastUpdated],
    ['Categories', titles(tool.categories, ctx.categories)],
    ['Standards', titles(tool.standards, ctx.standards)],
    ['Tags', tool.tags?.join(', ')],
    ['Endorsed by NAPCORE', tool.endorsed ? 'Yes' : undefined],
  ];
  return rows
    .filter(([, value]) => value)
    .map(([label, value]) => `- ${label}: ${value}`)
    .join('\n');
}

function toolHeader(tool: Tool, ctx: LlmsContext): string {
  return [`# ${tool.title}`, tool.description ? `> ${tool.description}` : '', '## Quick Info', toolQuickInfo(tool, ctx)]
    .filter(Boolean)
    .join('\n\n');
}

/** Full page for a registry (publiccode) tool. */
export function registryToolMarkdown(tool: Tool, ctx: LlmsContext): string {
  const parts = [toolHeader(tool, ctx)];
  if (tool.longDescription) parts.push('## Description', tool.longDescription);
  if (tool.features?.length) parts.push('## Features', tool.features.map((f) => `- ${f}`).join('\n'));
  return parts.join('\n\n');
}

/** Full page for a standard. */
export function standardMarkdown(slug: string, ctx: LlmsContext): string | undefined {
  const s = ctx.standards[slug];
  if (!s) return undefined;
  const facts: [string, string | undefined][] = [
    ['Full name', s.longTitle],
    ['Domain', s.domain],
    ['Status', s.status],
    ['Format/Technology', s.format_technology],
    ['Maintainer/Origin', s.maintainer_origin],
    ['More info', s.link],
  ];
  const parts = [`# ${s.title}`];
  if (s.description) parts.push(`> ${s.description}`);
  parts.push(
    facts
      .filter(([, v]) => v)
      .map(([k, v]) => `- ${k}: ${v}`)
      .join('\n')
  );
  if (s.purpose) parts.push(s.purpose.trim());
  if (s.related_standards?.length) parts.push('## Related Standards', standardList(s.related_standards, ctx));
  parts.push('## Tools', toolList(ctx.tools.filter((t) => t.standards?.includes(slug))));
  return parts.join('\n\n');
}

/** Full page for a category generated from categories.yaml. */
export function categoryMarkdown(slug: string, ctx: LlmsContext): string | undefined {
  const c = ctx.categories[slug];
  if (!c) return undefined;
  const parts = [`# ${c.title}`, c.description];
  if (c.related?.length) parts.push('## Related Categories', categoryList(c.related, ctx));
  parts.push('## Available Tools', toolList(ctx.tools.filter((t) => t.categories.includes(slug))));
  return parts.join('\n\n');
}

/** Replaces Vue components in a hand-crafted page with the text they would show. */
export function replaceComponents(body: string, section: string, slug: string, ctx: LlmsContext): string {
  const toolsInCategory = () => toolList(ctx.tools.filter((t) => t.categories.includes(slug)));
  return (
    body
      .replace(/<ToolsFilter\s+:endorsed-only="true"\s*\/>/g, () => toolList(ctx.tools.filter((t) => t.endorsed)))
      .replace(/<ToolsFilter\s+:show-all=\S+\s*\/>/g, () => toolList(ctx.tools))
      .replace(/<ToolsFilter\s*\/>/g, () => (section === 'categories' ? toolsInCategory() : toolList(ctx.tools)))
      .replace(/<ToolsGrid\s+:selectedTools="\[([^\]]*)\]"\s*\/>/g, (_m, list: string) => {
        const wanted = [...list.matchAll(/'([^']+)'/g)].map((m) => m[1]);
        return toolList(ctx.tools.filter((t) => wanted.includes(t.slug)));
      })
      .replace(/<RelatedCategories\s*\/>/g, () => categoryList(ctx.categories[slug]?.related ?? [], ctx))
      .replace(/<RelatedStandards\s*\/>/g, () => standardList(ctx.standards[slug]?.related_standards ?? [], ctx))
      .replace(/<CategoriesFilter[^>]*\/>/g, () => categoryList(Object.keys(ctx.categories), ctx))
      .replace(/<StandardsFilter\s*\/>/g, () => standardList(Object.keys(ctx.standards), ctx))
      // Links bound through withBase(), used where a Markdown link would be rewritten to .html
      .replace(/<a :href="withBase\('([^']+)'\)"[^>]*>([^<]*)<\/a>/g, '[$2]($1)')
      // Anything else (stats bars, blog widgets, ToolMetadata) has no text equivalent
      .replace(/^[ \t]*<[A-Z][A-Za-z]*\b[^>]*\/>[ \t]*$/gm, '')
  );
}

/**
 * Rewrites one per-page `.md` file. Keeps the plugin's frontmatter (URL, LLMS_URL, …)
 * and replaces the body with clean Markdown.
 */
export function cleanLlmsPage(page: LlmsPage, ctx: LlmsContext): LlmsPage {
  const pagePath = toUrlPath(page.path);
  const head = FRONTMATTER.exec(page.content)?.[0] ?? '';
  let body = page.content
    .slice(head.length)
    .replace(/\r\n/g, '\n')
    // The plugin cannot strip CRLF frontmatter, so the source frontmatter may still be here
    .replace(FRONTMATTER, '')
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/g, '');

  const match = /^\/(tools|standards|categories)\/([^/]+)\.md$/.exec(pagePath);
  const [, section, slug] = match ?? [];
  const isDynamic = Boolean(match) && !ctx.hasSourceFile(pagePath);

  let generated: string | undefined;
  if (isDynamic && section === 'tools') {
    const tool = ctx.tools.find((t) => t.slug === slug);
    if (tool) generated = registryToolMarkdown(tool, ctx);
  } else if (isDynamic && section === 'standards') {
    generated = standardMarkdown(slug, ctx);
  } else if (isDynamic && section === 'categories') {
    generated = categoryMarkdown(slug, ctx);
  }

  if (generated) {
    body = generated;
  } else {
    if (section === 'tools' && page.frontmatter.document === 'tool') {
      const tool = ctx.tools.find((t) => t.slug === slug);
      if (tool) body = `${toolHeader(tool, ctx)}\n\n${body}`;
    }
    body = replaceComponents(body, section ?? '', slug ?? '', ctx);
  }

  const link = (url: string) => withBasePath(toUrlPath(url), ctx.base);
  body = body
    .replace(/\]\((\/[^)\s]*)\)/g, (_m, url: string) => `](${link(url)})`)
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  const fixedHead = head.replace(
    /^(URL|LLMS_URL): "(.*)"$/gm,
    (_m, key: string, url: string) => `${key}: "${link(url)}"`
  );
  return { ...page, path: pagePath, url: link(page.url), llmUrl: link(page.llmUrl), content: `${fixedHead}${body}\n` };
}
